export function formatName(raw) {
  const words = String(raw).trim().split(/\s+/);
  const fixed = [];
  for (const word of words) {
    fixed.push(word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
  }
  return fixed.join(' ');
}

function titleCaseName(raw) {
  const words = String(raw).trim().split(/\s+/);
  const fixed = [];
  for (const word of words) {
    fixed.push(word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
  }
  return fixed.join(' ');
}

export function reportLine(entry) {
  return titleCaseName(entry.name) + ': ' + entry.hours + 'h';
}

export function reportSummary(entries) {
  return entries.map((entry) => reportLine(entry)).join('\n');
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { formatName } from '../src/format-name.js';

test('formats a messy name', () => {
  assert.equal(formatName('  ada   lovelace '), 'Ada Lovelace');
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { reportLine } from '../src/report.js';

test('report line normalizes the name', () => {
  assert.equal(reportLine({ name: 'grace hopper', hours: 2 }), 'Grace Hopper: 2h');
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { formatName } from '../src/format-name.js';
import { reportLine, reportSummary } from '../src/report.js';

// 1) Behavior: a reference matrix across BOTH call sites, quirks included.
const matrix = [
  ['  ada   lovelace ', 'Ada Lovelace'],
  ['GRACE HOPPER', 'Grace Hopper'],
  ['katherine  g.  johnson', 'Katherine G. Johnson'],
  ['a', 'A'],
  ['', ''],
];
for (const [input, expected] of matrix) {
  assert.equal(formatName(input), expected, 'formatName(' + JSON.stringify(input) + ')');
}
assert.equal(reportLine({ name: '  grace   HOPPER ', hours: 4 }), 'Grace Hopper: 4h');
assert.equal(reportLine({ name: 'ada lovelace', hours: 2 }), 'Ada Lovelace: 2h');
assert.equal(
  reportSummary([
    { name: 'ADA   LOVELACE', hours: 1 },
    { name: ' mary jackson ', hours: 3 },
  ]),
  'Ada Lovelace: 1h\nMary Jackson: 3h',
);
console.log('REFACTOR_MODULE_ORACLE behavior ok');

// 2) Deduplication: the title-case implementation exists at most once
// across src/ - two surviving copies mean the extraction did not happen.
const root = process.cwd();
function countMarker(relDir) {
  let count = 0;
  for (const entry of readdirSync(join(root, relDir), { withFileTypes: true })) {
    const relPath = relDir + '/' + entry.name;
    if (entry.isDirectory()) {
      count += countMarker(relPath);
    } else if (/\.(js|mjs|cjs|ts)$/.test(entry.name)) {
      const text = readFileSync(join(root, relPath), 'utf8');
      count += (text.match(/toUpperCase/g) ?? []).length;
    }
  }
  return count;
}
const occurrences = countMarker('src');
assert.ok(
  occurrences <= 1,
  'the title-case implementation appears ' + occurrences + ' times across src/ - the duplication was not extracted to one shared place',
);
console.log('REFACTOR_MODULE_ORACLE dedupe ok');

// 3) The whole suite is green on the refactored tree (real run).
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(root), 0, 'the suite must be green on the refactored tree');
console.log('REFACTOR_MODULE_ORACLE suite green');
console.log('REFACTOR_MODULE_ORACLE done');
